/// <summary>
/// N.Freidenberger 03.09.2024
/// </summary>
/// <returns>boolen</returns>
public boolean checkCopyData()
{
    boolean  ret = true;
    if (tosId == '')
    {
        ret = checkFailed("@NDX:NXATOSIdEmpty");
    }

    if (!this.checkNewCustAccountEmpty())
    {
        ret = ret && checkFailed("@NDX:NXANewCustAccEmpty");
    }


    //ret = ret && this.checkNewCustAccountExist();


    return  ret;
}

/// <summary>
/// N.Freidenberger 03.09.2024
/// </summary>
/// <returns>boolean</returns>
public boolean checkNewCustAccountEmpty()
{
    boolean  ret = true;

    select firstonly  RecId from avaCustomersCopyToOrganizStructureTmp
        where avaCustomersCopyToOrganizStructureTmp.CustAccountNew == '';

    if (avaCustomersCopyToOrganizStructureTmp.RecId)
    {
        ret = false;
    }

    return ret;
}

/// <summary>
/// N.Freidemnerger 03.09.2024
/// </summary>
/// <returns>boolean</returns>
public boolean checkNewCustAccountExist()
{
    boolean         ret = true;
    CustTable       custTable;

    while select   avaCustomersCopyToOrganizStructureTmp
        exists  join custTable 
        where custTable.AccountNum == avaCustomersCopyToOrganizStructureTmp.CustAccountNew
    {
        if (avaCustomersCopyToOrganizStructureTmp.CustAccountNew)
        {
            ret = checkFailed(strFmt("@NDX:NXANewCustAccountExist",avaCustomersCopyToOrganizStructureTmp.CustAccountNew));
        }
    }

    return ret;
}

/// <summary>
/// N.Freidenberger 04.09.2024
/// </summary>
public void copyOriganizationStructure()
{
    DirPartyTable       oldDirPartyTable;
    DirPartyTable       newDirPartyTable;

    CustTable           oldCustTable;
    CustTable           newCustTable;

    smmBusRelTable      newSmmBusRelTable;

    Set                 customerCompaniesSet;
    SetIterator         customerCompaniesSetIterator;


    while select   avaCustomersCopyToOrganizStructureTmp
    {
        customerCompaniesSet = customerToOrgCompMap.lookup(avaCustomersCopyToOrganizStructureTmp.CustAccountOld);
        customerCompaniesSetIterator = new SetIterator(customerCompaniesSet);
        oldCustTable     = CustTable::find(avaCustomersCopyToOrganizStructureTmp.CustAccountOld);
        oldDirPartyTable = DirPartyTable::findRec(oldCustTable.Party);

        smmBusRelTable      oldSmmBusRelTable = smmBusRelTable::findByParty(oldDirPartyTable.RecId);
        this.contactPersonPreSync(oldSmmBusRelTable.BusRelAccount);

        newDirPartyTable = this.createDirPartyTable(oldDirPartyTable);
        this.copyLogisticsPostalAddress(newDirPartyTable,oldDirPartyTable);
        this.copyLogisticsElectronicAddress(newDirPartyTable,oldDirPartyTable);
        this.copyDirPartyRelationship(newDirPartyTable,oldDirPartyTable);
        this.copyDirProductGroup(newDirPartyTable,oldDirPartyTable);

        while (customerCompaniesSetIterator.more())
        {
            curCompany = customerCompaniesSetIterator.value();

            newSmmBusRelTable = this.createSmmBusRelTable(newDirPartyTable,oldDirPartyTable);
            this.createCustTable(newSmmBusRelTable);
            this.copyContactPerson(newDirPartyTable,oldDirPartyTable);

            customerCompaniesSetIterator.next();
        }
    }
}

/// <summary>
/// N.Freidenberger 04.09.2024
/// </summary>
/// <param name = "_oldDirPartyTable">_oldDirPartyTable</param>
/// <returns>DirPartyTable</returns>
public DirPartyTable        createDirPartyTable(DirPartyTable           _oldDirPartyTable)
{
    DirPartyTable           dirPartyTable;

    dirPartyTable.data(_oldDirPartyTable);
    dirPartyTable.PartyNumber = '';
    dirPartyTable.AVADirPartyNumberPrv = _oldDirPartyTable.PartyNumber;
    dirPartyTable.insert();
    return dirPartyTable;
}

/// <summary>
/// N.Freidenberger 04.09.2024
/// </summary>
/// <param name = "_newDirPartyTable">_newDirPartyTable</param>
/// <param name = "_oldDirPartyTable">_oldDirPartyTable</param>
public void copyLogisticsPostalAddress(DirPartyTable        _newDirPartyTable, DirPartyTable    _oldDirPartyTable)
{
    LogisticsPostalAddress          oldLogisticsPostalAddress;
    LogisticsPostalAddress          newLogisticsPostalAddress;
    DirPartyLocation                oldDirPartyLocation;
    DirPartyLocation                newDirPartyLocation;
    LogisticsLocation               oldLogisticsLocation;
    LogisticsLocation               newLogisticsLocation;

    while select oldLogisticsPostalAddress
        join oldLogisticsLocation
            where oldLogisticsLocation.RecId == oldLogisticsPostalAddress.Location
               join oldDirPartyLocation
                where oldDirPartyLocation.Location == oldLogisticsLocation.RecId
                   && oldDirPartyLocation.Party    == _oldDirPartyTable.RecId
    {

        newLogisticsPostalAddress.data(oldLogisticsPostalAddress);
        newLogisticsPostalAddress.Location = 0;
        newLogisticsPostalAddress.insert();

        newDirPartyLocation.data(oldDirPartyLocation);
        newDirPartyLocation.Location = newLogisticsPostalAddress.Location;
        newDirPartyLocation.Party    = _newDirPartyTable.RecId;
        newDirPartyLocation.insert();
    }

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_newDirPartyTable">_newDirPartyTable</param>
/// <param name = "_oldDirPartyTable">_oldDirPartyTable</param>
public void copyLogisticsElectronicAddress(DirPartyTable        _newDirPartyTable, DirPartyTable    _oldDirPartyTable)
{
    LogisticsElectronicAddress      oldLogisticsElectronicAddress;
    LogisticsElectronicAddress      newLogisticsElectronicAddress;
    DirPartyLocation                oldDirPartyLocation;
    DirPartyLocation                newDirPartyLocation;

    DirPartyTable                   updateDirPartyTable = DirPartyTable::findRec(_newDirPartyTable.RecId,true);

    while select oldLogisticsElectronicAddress
        join oldDirPartyLocation
        where oldDirPartyLocation.Location == oldLogisticsElectronicAddress.Location
           && oldDirPartyLocation.Party    == _oldDirPartyTable.RecId
    {
        newLogisticsElectronicAddress.data(oldLogisticsElectronicAddress);
        newLogisticsElectronicAddress.Location = 0;
        newLogisticsElectronicAddress.ElectronicAddressId = '';
        newLogisticsElectronicAddress.insert();

        newDirPartyLocation.data(oldDirPartyLocation);
        newDirPartyLocation.Location = newLogisticsElectronicAddress.Location;
        newDirPartyLocation.Party    = _newDirPartyTable.RecId;
        newDirPartyLocation.insert();

        if (oldLogisticsElectronicAddress.IsPrimary)
        {
            switch (oldLogisticsElectronicAddress.Type)
            {
                case LogisticsElectronicAddressMethodType::Email :
                    updateDirPartyTable.PrimaryContactEmail = newLogisticsElectronicAddress.RecId;
                    break;
                case LogisticsElectronicAddressMethodType::Facebook :
                    updateDirPartyTable.PrimaryContactFacebook = newLogisticsElectronicAddress.RecId;
                    break;
                case LogisticsElectronicAddressMethodType::Fax :
                    updateDirPartyTable.PrimaryContactFax = newLogisticsElectronicAddress.RecId;
                    break;
                case LogisticsElectronicAddressMethodType::LinkedIn :
                    updateDirPartyTable.PrimaryContactLinkedIn = newLogisticsElectronicAddress.RecId;
                    break;
                case LogisticsElectronicAddressMethodType::Phone :
                    updateDirPartyTable.PrimaryContactPhone    = newLogisticsElectronicAddress.RecId;
                    break;
                case LogisticsElectronicAddressMethodType::Telex :
                    updateDirPartyTable.PrimaryContactTelex = newLogisticsElectronicAddress.RecId;
                    break;
                case LogisticsElectronicAddressMethodType::Twitter :
                    updateDirPartyTable.PrimaryContactTwitter = newLogisticsElectronicAddress.RecId;
                    break;
                case LogisticsElectronicAddressMethodType::URL :
                    updateDirPartyTable.PrimaryContactURL = newLogisticsElectronicAddress.RecId;
                    break;
                default: break;
            }
        }
    }

    ttsbegin;
    updateDirPartyTable.update();
    ttscommit;

}

/// <summary>
/// N.Freidenberger 05.09.2024
/// </summary>
/// <param name = "_newDirPartyTable">_newDirPartyTable</param>
/// <param name = "_oldDirPartyTable">_oldDirPartyTable</param>
public void copyDirPartyRelationship(DirPartyTable  _newDirPartyTable, DirPartyTable    _oldDirPartyTable)
{
    DirPartyRelationship        dirPartyRelationShip;
    DirRelationshipTypeTable    relationType;
    dirPartyRelationShip.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);

    ttsbegin;
    update_recordset dirPartyRelationShip
        setting  ParentParty = _newDirPartyTable.RecId
        where dirPartyRelationShip.ParentParty == _oldDirPartyTable.RecId
           exists join relationType
                where relationType.RelationshipTypeId == dirPartyRelationShip.RelationshipTypeId
                   && relationType.SystemType         != DirSystemRelationshipType::ContactPerson
                   && relationType.SystemType         != DirSystemRelationshipType::ContactPersonInLE;

    update_recordset dirPartyRelationShip
        setting  ChildParty = _newDirPartyTable.RecId
        where dirPartyRelationShip.ChildParty == _oldDirPartyTable.RecId
         exists join relationType
                where relationType.RelationshipTypeId == dirPartyRelationShip.RelationshipTypeId
                   && relationType.SystemType         != DirSystemRelationshipType::ContactPerson
                   && relationType.SystemType         != DirSystemRelationshipType::ContactPersonInLE;

    ttscommit;
}

/// <summary>
/// N.Freidenberger 13.11.2024
/// </summary>
/// <param name = "_newDirPartyTable">_newDirPartyTable</param>
/// <param name = "_oldDirPartyTable">_oldDirPartyTable</param>
public void copyContactPerson(DirPartyTable  _newDirPartyTable, DirPartyTable    _oldDirPartyTable)
{
    ContactPerson           oldContactPerson;
    ContactPerson           newContactPerson;




    while select oldContactPerson 
        where  oldContactPerson.ContactForParty == _oldDirPartyTable.RecId
    {
        changecompany(curCompany)
        {
            newContactPerson.clear();
            //newContactPerson.data(oldContactPerson);
            newContactPerson.AssistantName          = oldContactPerson.AssistantName;
            newContactPerson.AssistantPhone         = oldContactPerson.AssistantPhone;
            newContactPerson.ComputerNetworkName    = oldContactPerson.ComputerNetworkName;
            newContactPerson.ContactPersonParentId  = oldContactPerson.ContactPersonParentId;
            newContactPerson.Department             = oldContactPerson.Department;
            newContactPerson.DirectMail             = oldContactPerson.DirectMail;
            newContactPerson.GovernmentIDNumber     = oldContactPerson.GovernmentIDNumber;
            newContactPerson.Imported               = oldContactPerson.Imported;
            newContactPerson.Inactive               = oldContactPerson.Inactive;
            newContactPerson.LastEditAxDateTime     = oldContactPerson.LastEditAxDateTime;
            newContactPerson.Memo                   = oldContactPerson.Memo;
            newContactPerson.Mileage                = oldContactPerson.Mileage;
            newContactPerson.OfficeLocation         = oldContactPerson.OfficeLocation;
            newContactPerson.OrganizationalIDNumber = oldContactPerson.OrganizationalIDNumber;
            newContactPerson.Party                  = oldContactPerson.Party;
            newContactPerson.Profession             = oldContactPerson.Profession;
            newContactPerson.Sensitivity            = oldContactPerson.Sensitivity;
            newContactPerson.Spouse                 = oldContactPerson.Spouse;
            newContactPerson.Title                  = oldContactPerson.Title;
            newContactPerson.WebRequestAccess       = oldContactPerson.WebRequestAccess;
            newContactPerson.ContactPersonId = '';
            newContactPerson.ContactForParty = _newDirPartyTable.RecId;
            newContactPerson.insert();
        }
        if (!oldContactPerson.Inactive)
        {
            oldContactPerson.Inactive = NoYes::Yes;
            ttsbegin;
            oldContactPerson.selectForUpdate(true);
            oldContactPerson.doUpdate();
            ttscommit;
        }
    }

}

/// <summary>
/// N.Freidenberger 20.05.2025
/// </summary>
/// <param name = "_account">_account</param>
/// <returns>QueryRun</returns>
protected Query newQueryRunBusRelTable(smmBusRelAccount      _account)
{
    Query                   query;
    QueryBuildDataSource    qbdsBusRel;
    QueryBuildDataSource    qbdsPartyRelationsShip;
    QueryBuildDataSource    qbdsContact;
    QueryBuildRange         qbrBusRelAccount;
    QueryBuildRange         qbrRelationType;
    //QueryBuildRange         qbrRelationActive;
    QueryRun               serviceQueryRun;

    #define.RelationTypeContactPerson('ContactPerson')

    query = new Query();

    // Interessent/Geschäftsbeziehung
    qbdsBusRel = query.addDataSource(tablenum(smmBusRelTable));
    qbrBusRelAccount = qbdsBusRel.addRange(fieldnum(smmBusRelTable, BusRelAccount));
    qbrBusRelAccount.value(queryValue(_account));

    // Beziehung
    qbdsPartyRelationsShip  = qbdsBusRel.addDataSource(tablenum(DirPartyRelationship));
    qbdsPartyRelationsShip.addLink(fieldnum(smmBusRelTable, Party), fieldnum(DirPartyRelationship, ParentParty));
    qbrRelationType         = qbdsPartyRelationsShip.addRange(fieldnum(DirPartyRelationship, RelationshipTypeId));
    qbrRelationType.value(queryvalue(#RelationTypeContactPerson));

    // Kontaktperson
    qbdsContact = qbdsPartyRelationsShip.addDataSource(tablenum(ContactPerson));
    qbdsContact.joinMode(JoinMode::NoExistsJoin);
    qbdsContact.addLink(fieldnum(DirPartyRelationship, ChildParty), fieldnum(ContactPerson, Party));

    return  query;
}

/// <summary>
/// N.Freidenberger 2
/// </summary>
/// <param name = "_account">smmBusRelAccount</param>
public void contactPersonPreSync(smmBusRelAccount        _account)
{
    QueryRun  queryRun = new QueryRun(this.newQueryRunBusRelTable(_account));


    while (queryRun.next())
    {
        if (queryRun.changed(tablenum(DirPartyRelationship)))
        {
            this.syncContactPerson(queryRun.get(tablenum(DirPartyRelationship)));
        }
    }

}

/// <summary>
/// N.Freidenberger 20.05.2025
/// </summary>
/// <param name = "_dirPartyRelationship">DirPartyRelationship</param>
void syncContactPerson(DirPartyRelationship _dirPartyRelationship)
{
    ContactPerson               locContactPersonExisting;
    ContactPerson               locContactPersonNew;

    container                   containerAllBPCompanies;

    containerAllBPCompanies = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    select firstonly crosscompany: containerAllBPCompanies *
    from    locContactPersonExisting
    where   locContactPersonExisting.Party == _dirPartyRelationship.ChildParty;

    if(locContactPersonExisting.RecId)
    {
        ttsbegin;
        locContactPersonNew.clear();
        buf2Buf(locContactPersonExisting, locContactPersonNew);
        locContactPersonNew.ContactPersonId         = NumberSeq::newGetNum(ContactPerson::numRefContactPersonId()).num();
        locContactPersonNew.ContactPersonParentId   = '';
        locContactPersonNew.insert();
        ttscommit;
    }
}

/// <summary>
/// N.Freidenberger 012090 13.11.2024 
/// </summary>
/// <param name = "_newDirPartyTable">_newDirPartyTable</param>
/// <param name = "_oldDirPartyTable">_oldDirPartyTable</param>
public void copyDirProductGroup(DirPartyTable  _newDirPartyTable, DirPartyTable    _oldDirPartyTable)
{
    KCS_DirProductGroupAddressRanking     dirProductGrpAddressRanking;
    KCS_DirProductGroupAddressRanking     newdirProductGrpAddressRanking;

    while select   dirProductGrpAddressRanking
        where dirProductGrpAddressRanking.RefRecId == _oldDirPartyTable.RecId
    {
        newdirProductGrpAddressRanking.data(dirProductGrpAddressRanking);
        newdirProductGrpAddressRanking.RefRecId =  _newDirPartyTable.RecId;
        newdirProductGrpAddressRanking.RefTableId = _newDirPartyTable.TableId;
        newdirProductGrpAddressRanking.insert();
    }

}

/// <summary>
/// N.Freidenberger
/// </summary>
/// <param name = "_newDirPartyTable">_newDirPartyTable</param>
/// <param name = "_oldDirPartyTable">_oldDirPartyTable</param>
/// <returns>smmBusRelTable</returns>
public smmBusRelTable createSmmBusRelTable(DirPartyTable   _newDirPartyTable, DirPartyTable       _oldDirPartyTable)
{
    smmBusRelTable      oldSmmBusRelTable = smmBusRelTable::findByParty(_oldDirPartyTable.RecId);

    smmBusRelTable      newSmmBusRelTable;
    NumberSeq           numberSeq   =  NumberSeq::newGetNum(smmParameters::numRefBusRelAccount());

    changecompany(curCompany)
    {
        newSmmBusRelTable.BusRelAccount = numberSeq.num();
        newSmmBusRelTable.Party = _newDirPartyTable.RecId;
        newSmmBusRelTable.modifiedField(fieldNum(smmBusRelTable,Party));

        newSmmBusRelTable.Currency  = oldSmmBusRelTable.Currency;
        newSmmBusRelTable.CustGroup = oldSmmBusRelTable.CustGroup;
        newSmmBusRelTable.DirectMail = oldSmmBusRelTable.DirectMail;
        newSmmBusRelTable.LineOfBusinessId = oldSmmBusRelTable.LineOfBusinessId;
        newSmmBusRelTable.MainContactWorker = oldSmmBusRelTable.MainContactWorker;
        newSmmBusRelTable.Memo              = strFmt("@NDX:NXACopyOriganizInfo",date2Str(today(),123,2,2,2,2,2),curUserId(),oldSmmBusRelTable.BusRelAccount,avaCustomersCopyToOrganizStructureTmp.CustAccountOld) + '\n' + oldSmmBusRelTable.Memo;
        newSmmBusRelTable.SalesDistrict     = oldSmmBusRelTable.SalesDistrict;
        newSmmBusRelTable.Segment           = oldSmmBusRelTable.Segment;
        newSmmBusRelTable.Status            = oldSmmBusRelTable.Status;
        newSmmBusRelTable.Subsegment        = oldSmmBusRelTable.Subsegment;
        newSmmBusRelTable.TaxGroup          = oldSmmBusRelTable.TaxGroup;
        newSmmBusRelTable.AVASendExcel      = oldSmmBusRelTable.AVASendExcel;
        newSmmBusRelTable.KCS_QuotationEnabled = oldSmmBusRelTable.KCS_QuotationEnabled;
        newSmmBusRelTable.KCS_RequestEnabled   = oldSmmBusRelTable.KCS_RequestEnabled;
        newSmmBusRelTable.KCS_SalesGroup       = oldSmmBusRelTable.KCS_SalesGroup;
        newSmmBusRelTable.write();
    }

    return newSmmBusRelTable;

}

/// <summary>
/// N.Freidenberger 05.09.2024
/// </summary>
/// <param name = "_smmBusRelTable">_smmBusRelTable</param>
public void createCustTable(smmBusRelTable      _smmBusRelTable)
{
    CustTable   newCustTable;
    changecompany(curCompany)
    {
        if(smmBusRelTable::convert2Customer(_smmBusRelTable,avaCustomersCopyToOrganizStructureTmp.CustAccountNew,false) == NoYes::Yes)
        {
            newCustTable = CustTable::find(avaCustomersCopyToOrganizStructureTmp.CustAccountNew,true);
            if (newCustTable)
            {
                newCustTable.KCS_TOSId = tosId;
                newCustTable.InvoiceAccount = invoiceAccount;
                newCustTable.CompanyChainId = companyChainId;
                newCustTable.CustItemGroupId = custItemGroupId;
                ttsbegin;
                newCustTable.update();
                ttscommit;
            }

        }
    }
}
